import {original} from './content.js';
import {sections, wireSections} from './sections.js';
let lang = localStorage.getItem('hompilot-lang') || 'en';
if (!['en','fr'].includes(lang)) lang='en';
const iconPaths={arrow:'M4 12h16m-6-6 6 6-6 6',play:'m9 5 11 7-11 7Z',check:'m5 12 4 4L19 6',phone:'M22 16.9v3a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 11.2 19a19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L8 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 2Z',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z',home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm8 .1a4 4 0 0 1 0 7.8',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Zm0 0v6h6M8 13h8m-8 4h5',bolt:'m13 2-9 12h7l-1 8 10-12h-7Z',message:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8Z',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',plus:'M12 5v14M5 12h14',sound:'m11 5-6 4H2v6h3l6 4Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',mute:'m11 5-6 4H2v6h3l6 4Zm6 4 5 6m-5 0 5-6',pause:'M8 5v14M16 5v14',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'m12 3 8 4v6c0 4-8 8-8 8s-8-4-8-8V7Zm-4 9 3 3 5-6',spark:'m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8Z',chevron:'m8 5 7 7-7 7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.spark}"/></svg>`;
const choose=(en,fr)=>lang==='fr'?fr:en;
const a=(label,href='#booking',style='red')=>`<a class="button ${style}" href="${href}">${label}${icon('arrow')}</a>`;
function header(t){return `<a class="skip-link" href="#main">${choose('Skip to content','Aller au contenu')}</a><header class="site-header"><div class="container nav"><a href="/" class="logo" aria-label="HomPilot"><img src="/brand/hompilot-logo.png" width="148" height="39" alt="HomPilot"></a><nav class="desktop-nav" aria-label="${choose('Main navigation','Navigation principale')}"><a href="#platform">${choose('Platform','Plateforme')}</a><a href="#maya">Maya <span class="small-tag">AI</span></a><a href="#solutions">Solutions</a><a href="#resources">${choose('Resources','Ressources')}</a></nav><div class="nav-actions"><div class="languages" aria-label="Language"><button data-lang="en" aria-pressed="${lang==='en'}">EN</button><span>/</span><button data-lang="fr" aria-pressed="${lang==='fr'}">FR</button></div>${a(t.nav.cta,'#booking','dark nav-cta')}<button class="menu-button icon-button" aria-expanded="false" aria-controls="mobile-nav" aria-label="${choose('Open menu','Ouvrir le menu')}">${icon('menu')}</button></div></div><nav id="mobile-nav" class="mobile-nav" hidden><a href="#platform">${choose('Platform','Plateforme')}</a><a href="#maya">Maya</a><a href="#solutions">Solutions</a><a href="#resources">${choose('Resources','Ressources')}</a>${a(t.nav.cta)}</nav></header>`;}
function hero(t){return `<section class="hero container"><div class="hero-copy"><p class="eyebrow"><span class="red-line"></span>${t.hero.badge}</p><h1>${choose('Run a smarter<br>home service<br><span>business.</span>','Votre entreprise.<br>Un temps<br><span>d’avance.</span>')}</h1><p class="hero-description">${t.hero.titleAccent}</p><div class="hero-actions">${a(t.nav.cta)}<button class="button outline" data-video="demo">${icon('play')}${t.hero.ctaSecondary}</button></div><div class="hero-trust"><span>${icon('check')}${choose('From $99/month','Dès 99 $/mois')}</span><span>${icon('check')}${choose('Cancel anytime','Sans engagement')}</span></div></div><div class="hero-visual"><div class="hero-visual-bg"></div><div class="portrait-window"><video class="maya-portrait" src="/brand/maya-agent-avatar.mp4" poster="/brand/maya-avatar.jpg" autoplay loop muted playsinline aria-label="${choose('Maya, your HomPilot AI receptionist','Maya, votre réceptionniste IA HomPilot')}"></video></div><div class="voice-bubble"><div class="voice-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><p>${choose('Hi, I’m Maya.<br>How can I help today?','Bonjour, je suis Maya.<br>Comment puis-je vous aider ?')}</p></div><div class="maya-label"><span class="availability"></span><div><strong>Maya</strong><span>${choose('Your AI receptionist · 24/7','Votre réceptionniste IA · 24/7')}</span></div><button class="icon-button portrait-pause" aria-label="${choose('Pause animation','Mettre l’animation en pause')}">${icon('pause')}</button></div><div class="appointment-float"><span class="status-icon">${icon('calendar')}</span><div><strong>${choose('Appointment booked','Rendez-vous confirmé')}</strong><span>${choose('The next job. Already handled.','Le prochain appel. Déjà pris en charge.')}</span></div>${icon('check','red-check')}</div><span class="visual-note">${choose('Always there. Already on it.','Toujours là. Toujours prête.')}</span></div></section>`;}
function trades(t){return `<section class="trade-strip"><div class="container trade-inner"><p>${choose('BUILT FOR THE PEOPLE<br>WHO KEEP HOMES RUNNING','POUR LES PROS<br>QUI PRENNENT SOIN DES MAISONS')}</p><div class="trade-items">${t.verticals.items.slice(0,5).map((x,i)=>`<span>${icon(['home','phone','bolt','shield','users'][i])}${x}</span>`).join('')}</div></div></section>`;}
function render(){const t=original[lang];document.documentElement.lang=lang;document.title=choose('HomPilot — Your business. A step ahead.','HomPilot — Votre entreprise. Un temps d’avance.');document.getElementById('app').innerHTML=header(t)+`<main id="main">${hero(t)}${trades(t)}${sections(t,lang,icon,a,choose)}`;bind();wireSections();}
function bind(){document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;localStorage.setItem('hompilot-lang',lang);render();}));const menu=document.querySelector('.menu-button');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);document.getElementById('mobile-nav').hidden=!open;menu.innerHTML=icon(open?'close':'menu');});document.querySelector('.portrait-pause')?.addEventListener('click',e=>{const video=document.querySelector('.maya-portrait');video.paused?video.play().catch(()=>{}):video.pause();e.currentTarget.innerHTML=icon(video.paused?'play':'pause');e.currentTarget.setAttribute('aria-label',video.paused?choose('Play animation','Lire l’animation'):choose('Pause animation','Mettre l’animation en pause'));});}
render();
